#ifndef IMPFE_CONFIG_H
#define IMPFE_CONFIG_H

/* Use <string.h> (glibc's also declares bzero/bcopy) */
#define I_STRING 1

/* Functions every Linux system has */
#define HAVE_BCOPY 1
#define HAVE_BZERO 1
#define HAVE_INDEX 1
#define HAVE_MEMCPY 1
#define HAVE_MEMMOVE 1
#define HAVE_MMAP 1
#define HAVE_MUNMAP 1
#define HAVE_STRCHR 1
#define HAVE_GETTIMEOFDAY 1
#define HAVE_SOCKET 1

#include <string.h>
#include <strings.h>

#endif /* IMPFE_CONFIG_H */
